type SourcePatch={name:string;before:string;after:string;changes:{old:string;new:string;count:number}[]}
function sourceBody(definition:string){
 const match=/\bAS\s+(\$[A-Za-z0-9_]*\$)/i.exec(definition)
 if(!match)throw Error('actual source body missing')
 const start=match.index+match[0].length,end=definition.indexOf(match[1],start)
 if(end<0)throw Error('actual source body terminator missing')
 return{body:definition.slice(start,end),start,end}
}
function loadActualOwners():Record<string,Owner>{
 const found:Record<string,Owner>={}
 for(const [name,expected] of Object.entries(expectedOwners)){
  let definition:string|undefined
  for(const [path,text] of Object.entries(sourceInputs)){
   const escaped=name.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')
   const starts=[...text.matchAll(new RegExp('^CREATE(?: OR REPLACE)? FUNCTION '+escaped+'\\s*\\(','gim'))]
   const start=starts.at(-1)
   if(start){
    const tail=text.slice(start.index),body=sourceBody(tail)
    const tag=/\bAS\s+(\$[A-Za-z0-9_]*\$)/i.exec(tail)![1]
    definition=tail.slice(0,body.end+tag.length+1)
   }
   if(definition&&text.includes('$specs$')){
    const patches=JSON.parse(text.split('$specs$')[1]) as SourcePatch[]
    for(const patch of patches.filter(p=>p.name===name)){
     const before=sourceBody(definition);let body=before.body
     if(createHash('sha256').update(body).digest('hex')!==patch.before)throw Error('actual before anchor changed: '+path+':'+name)
     for(const change of patch.changes){
      if(body.split(change.old).length-1!==change.count)throw Error('actual source occurrence changed: '+name)
      body=body.split(change.old).join(change.new)
     }
     if(createHash('sha256').update(body).digest('hex')!==patch.after)throw Error('actual after anchor changed: '+name)
     definition=definition.slice(0,before.start)+body+definition.slice(before.end)
    }
   }
  }
  if(!definition)throw Error('actual owner missing: '+name)
  const bodyHash=createHash('sha256').update(sourceBody(definition).body).digest('hex')
  const definitionHash=createHash('sha256').update(definition).digest('hex')
  if(bodyHash!==expected.prosrcSHA256||definitionHash!==expected.sha256)throw Error('actual qualified owner changed: '+name)
  found[name]={definition,sha256:definitionHash,prosrcSHA256:bodyHash}
 }
 return found
}
