 await db.exec(`DO $fixture$DECLARE d record;${decl}actor uuid:='${executor}';p_actor_user_id uuid:='${executor}';p_company_id uuid:='${company}';BEGIN ${row}${reviewed?'':`SELECT '${review}'::uuid AS id INTO r;`}${statement}END$fixture$;`)
