const sql=componentSQL
type RawDeleteContext={current_user:string;session_user:string;delete_grant:boolean;private_schema_usage:boolean;owner_member:boolean}
type PrivateACL={Aaccess:boolean;permitAccess:boolean;helperExecute:boolean}
type Failure={code?:string;message:string;where?:string}
type RawDeleteRow={role:string;component:boolean;before:number;context:RawDeleteContext;privateACL?:PrivateACL;guardSecurityDefiner?:boolean;deletion:{id:string}[]|null;error:Failure|null;after:number}
const results:RawDeleteRow[]=[]
it.each(['authenticated','service_role'] as const)('preservation: first raw audit DELETE under %s retains existing effect without private privilege',async role=>{
 for(const component of [false,true]){
  const db=await bootstrap()
  try{
   if(component)await installFixtureSQL(db,sql)
   await seed(db);await writerShape(db)
   const before=(await db.query<{n:number}>('SELECT count(*)::int n FROM public.audit_logs')).rows[0].n
   const ids=component?(await db.query<{a:number;p:number;f:number;sec:boolean}>("SELECT 'gridex_ediel_retention.audit19_approvals_v1'::regclass::oid a,'gridex_ediel_retention.audit19_permits_v1'::regclass::oid p,'gridex_ediel_retention.audit19_guard_v1()'::regprocedure::oid f,(SELECT prosecdef FROM pg_proc WHERE oid='gridex_ediel_retention.audit19_guard_v1()'::regprocedure) sec")).rows[0]:undefined
   await db.exec('SET SESSION AUTHORIZATION '+role)
   const context=(await db.query<RawDeleteContext>("SELECT current_user,session_user,has_table_privilege(current_user,'public.audit_logs','DELETE') delete_grant,has_schema_privilege(current_user,'gridex_ediel_retention','USAGE') private_schema_usage,pg_has_role(current_user,'gridex_ediel_retention_owner','MEMBER') owner_member")).rows[0]
   const privateACL=ids?(await db.query<PrivateACL>('SELECT has_table_privilege(current_user,$1::oid,\'SELECT,INSERT,UPDATE,DELETE\') "Aaccess",has_table_privilege(current_user,$2::oid,\'SELECT,INSERT,UPDATE,DELETE\') "permitAccess",has_function_privilege(current_user,$3::oid,\'EXECUTE\') "helperExecute"',[ids.a,ids.p,ids.f])).rows[0]:undefined
   let deletion:{id:string}[]|null=null,error:Failure|null=null
   try{deletion=(await db.query<{id:string}>('DELETE FROM public.audit_logs WHERE id=$1 AND company_id=$2 RETURNING id',[audit,company])).rows}
   catch(caught){const e=caught as Failure;error={code:e.code,message:e.message,where:e.where}}
   await db.exec('RESET SESSION AUTHORIZATION')
   const after=(await db.query<{n:number}>('SELECT count(*)::int n FROM public.audit_logs')).rows[0].n
   results.push({role,component,before,context,privateACL,guardSecurityDefiner:ids?.sec,deletion,error,after})
   expect(before).toBe(1);expect(context).toEqual({current_user:role,session_user:role,delete_grant:true,private_schema_usage:false,owner_member:false})
   if(component){expect(privateACL).toEqual({Aaccess:false,permitAccess:false,helperExecute:false});expect(ids?.sec).toBe(false)}
   expect(error).toBeNull();expect(deletion).toEqual([{id:audit}]);expect(after).toBe(0)
  }finally{await db.close()}
 }
},30000)
